add_action('wp_loaded', function(){
  if(!isset($_GET['ps_sn']) || $_GET['ps_sn']!=='Snx') return;
  global $wpdb; $o=array();
  $t=$wpdb->prefix.'snippets';
  if($wpdb->get_var("SHOW TABLES LIKE '$t'")){
    $rows=$wpdb->get_results("SELECT id,name,active,scope FROM $t WHERE code LIKE '%petshop_add_company_fields%' OR name LIKE '%mon%' OR name LIKE '%ompan%'",ARRAY_A);
    $o['snippetai']=$rows;
    foreach($rows as $r){
      $code=$wpdb->get_var($wpdb->prepare("SELECT code FROM $t WHERE id=%d",$r['id']));
      if(strpos($code,'petshop_add_company_fields')!==false){ $o['kodas']=$code; $o['snippet_id']=$r['id']; break; }
    }
  }
  header('Content-Type: application/json'); echo json_encode($o); exit;
});
